import csv,importlib.util,json,pathlib,statistics,subprocess,sys
root=pathlib.Path(__file__).resolve().parent;repo=pathlib.Path.cwd();sys.path.insert(0,str(repo/'scripts/perf'))
from avatar_tuning import sha256,summarize,run_order
spec=importlib.util.spec_from_file_location('compare',repo/'scripts/perf/compare-avatar-revisions.py');compare=importlib.util.module_from_spec(spec);spec.loader.exec_module(compare)
d=json.loads((root/'evaluation/summary.json').read_text());exp=d['experiment'];assert len(d['runs'])==8
assert [(r['round'],r['variant']) for r in d['runs']]==run_order(['baseline','candidate'],4)

def capture(p):
 samples=[]
 for line in (p/'samples.jsonl').read_text().splitlines():
  s=json.loads(line);h=s['health'];s['health']={'extended':{k:h['extended'][k] for k in ['appMessages','avatarSync','rawUdp','reliable']},'transport':h['transport']};samples.append(s)
 return {'process_samples':samples,'run_metadata':json.loads((p/'run.json').read_text()),'commands':json.loads((p/'commands.json').read_text()),'ready_health':json.loads((p/'ready-health.json').read_text()),'csv':{n:(p/n).read_text() for n in ['observer.csv','observer.sender.csv','server-pairs.global.csv','scene.csv']},'artifact_sha256':{f.name:sha256(f) for f in p.iterdir() if f.is_file()}}
d['raw_runs']={}
for entry,result in zip(exp['runs'],d['runs']):
 p=root/'evaluation'/entry['name'];view=dict(exp,frozen=dict(exp['frozen'],server=exp['frozen'][entry['variant']]))
 assert summarize(p,view,entry)==result
 c=capture(p);d['raw_runs'][entry['name']]=c
 retx=[s['health']['extended']['reliable']['retransmits'] for s in c['process_samples']]
 result['retransmits_observed']={'at_population_ready':c['ready_health']['extended']['reliable']['retransmits'],'first_sample':retx[0],'last_sample':retx[-1],'minimum':min(retx),'maximum':max(retx),'sample_window_delta':retx[-1]-retx[0]}
 result['failed_checks']=[k for k,v in result['checks'].items() if not v]
 for group,keys in {'appMessages':['avatarReceived','avatarCoalesced','avatarRejected','avatarProcessed'],'reliable':['pending','queued']}.items():
  result.setdefault('health_window',{})[group]={}
  for key in keys:
   vals=[s['health']['extended'][group].get(key) for s in c['process_samples']]
   result['health_window'][group][key]=None if any(v is None for v in vals) else {'first':vals[0],'last':vals[-1],'min':min(vals),'max':max(vals),'delta':vals[-1]-vals[0]}
for path,h in exp['tool_sha256'].items():assert sha256(pathlib.Path(path))==h
for artifact in exp['frozen'].values():assert sha256(pathlib.Path(artifact['path']))==artifact['sha256']
profile=exp['build']['profile']
for p in [*profile['raw_profiles'],profile['merged_profile']]:assert sha256(pathlib.Path(p['path']))==p['sha256']
d['raw_training']={}
for entry,result in zip(profile['training_experiment']['runs'],profile['training']):
 p=root/'training'/entry['name'];original=summarize(p,profile['training_experiment'],entry)
 assert all(original[k]==result[k] for k in original)
 assert result['checks']['completed'] and result['checks']['continuous_readiness']
 d['raw_training'][entry['name']]=capture(p)
d['local_controllers']={f:{'source':(root/f).read_text(),'sha256':sha256(root/f)} for f in ['drive-evaluation.py','continue-training.py','continue-series.py','retain-evidence.py']}
d['controller_logs']={p.name:{'source':p.read_text(),'sha256':sha256(p)} for p in root.glob('*controller.log')}
d['controller_logs']['training-continuation.log']={'source':(root/'training-continuation.log').read_text(),'sha256':sha256(root/'training-continuation.log')}
d['controller_logs']['driver.log']={'source':(root/'driver.log').read_text(),'sha256':sha256(root/'driver.log')}
d['comparison']=compare.aggregate(d['runs'],4)
d['analysis']={'power_profile_after':subprocess.check_output(['powerprofilesctl','get'],text=True).strip(),'ac_online_after':pathlib.Path('/sys/class/power_supply/ADP0/online').read_text().strip(),'purpose':'Same source ordinary versus freshly mixed-workload-trained PGO server with one ordinary Rust client','workload':exp['workload'],'independent_processes_per_variant':4,'training_clients':250,'evaluation_clients':1500,'training_diagnostic_only':True,'training_strict_valid_runs':sum(r['valid'] for r in profile['training']),'strict_valid_runs':sum(r['valid'] for r in d['runs']),'all_failed_runs_retained':True,'production_changes':False,'additional_data_validation':'Exact full/delta byte preservation verified by existing live-loopback test; large-run observer validates pose application, not exact additional bytes.','scene_scope':'Synthetic all-peer script relay; no asset loading, physics, ownership or Unity script execution.','measurement_windows':'CPU/server/avatar diagnostics fixed60s; scene starts first tick after shared marker and ends shutdown including2s receive grace, normalized by actual scene.csv duration.','limits':['One laptop, one training profile, four processes per variant; descriptive evidence only','250-client mixed training vs1500-client evaluation','Scene observer client0 measures one receiver; same-host latency histogram upper bounds','High offered scene fanout may exceed host capacity; delivery/cadence failures preclude clean PGO speedup claims','Loopback, voiceoff, CPU-only server, no network loss simulation']}
out=repo/'docs/performance/results/pgo-mixed-client1500-20261010-summary.json';out.write_text(json.dumps(d,indent=2,allow_nan=False)+'\n')
print(json.dumps({'output':str(out),'analysis':d['analysis'],'statistics':d['comparison']['statistics'],'failed':{r['name']:r['failed_checks'] for r in d['runs']}},indent=2))
